method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // lst must be a non-empty list
    ensures forall i :: 0 <= i < |lst| ==> (i % 2 == 1 && lst[i] % 2 == 0 ==> result == SumEvenAtOddIndices(lst))
{
    result := 0;
    var i := 1;
    while i < |lst|
        invariant 0 <= i <= |lst| // i is within bounds of lst
        invariant result == SumEvenAtOddIndices(lst[..i]) // result is the sum of even elements at odd indices up to i
    {
        if lst[i] % 2 == 0 {
            result := result + lst[i];
        }
        i := i + 2; // incrementing by 2 to only check odd indices
    }
}

function SumEvenAtOddIndices(lst: seq<int>) : int
    reads lst
    ensures result == (if |lst| == 0 then 0 else SumEvenAtOddIndices(lst[1..])) + (if |lst| > 1 && lst[0] % 2 == 0 then lst[0] else 0)
{
    if |lst| == 0 then 0
    else if |lst| == 1 then 0
    else if lst[0] % 2 == 0 then lst[0] + SumEvenAtOddIndices(lst[2..]) // including the even element at odd index
    else SumEvenAtOddIndices(lst[2..]) // skipping the odd element
}
